const cfg = $('Config').first().json;

// n8n HTTP Request JSON dizi donerse cogunlukla her satiri ayri item yapar.
// Bazen de tek item icinde dizi / fullResponse.body gelir.
function asRows(inputItems) {
  if (!inputItems.length) return [];

  // Cok item: her biri bir ilce satiri
  if (inputItems.length > 1) {
    return inputItems.map((i) => i.json).filter((r) => r && r.il && r.ilce);
  }

  let body = inputItems[0].json;
  if (Array.isArray(body)) return body;
  if (body && Array.isArray(body.body)) return body.body;
  if (body && typeof body.body === 'string') {
    try {
      const parsed = JSON.parse(body.body);
      if (Array.isArray(parsed)) return parsed;
    } catch (_) {}
  }
  if (typeof body === 'string') {
    try {
      const parsed = JSON.parse(body);
      if (Array.isArray(parsed)) return parsed;
      body = parsed;
    } catch (_) {}
  }
  // Tek item, tek satir (limit=1 gibi)
  if (body && body.il && body.ilce) return [body];
  // PostgREST hata objesi
  if (body && (body.message || body.code || body.error)) {
    throw new Error('ilce_merkezleri fetch hata: ' + JSON.stringify(body).slice(0, 400));
  }
  throw new Error(
    'ilce_merkezleri dizi degil; keys=' +
      Object.keys(body || {}).slice(0, 20).join(',') +
      ' typeof=' + typeof body
  );
}

const rows = asRows($input.all());
if (rows.length < 100) {
  throw new Error('Beklenen ~134 ilce, gelen=' + rows.length);
}
if (!String(cfg.supabaseServiceRoleKey || '').trim() || String(cfg.supabaseServiceRoleKey).startsWith('REPLACE_ME')) {
  throw new Error("Config.supabaseServiceRoleKey doldur (Panorama Config'ten kopyala).");
}
return rows.map((r) => ({ json: r }));

const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.lat != null && r.lon != null);
const OFFSET = 0.018;
const skipDays = Number(cfg.skipDays);
const SKIP_MS = (Number.isFinite(skipDays) ? skipDays : 25) * 24 * 60 * 60 * 1000;
const now = Date.now();
const YOGUN_KEY = 'yo\u011fun_bolge';
function isFresh(sonTarama) {
  if (!sonTarama) return false;
  const t = new Date(sonTarama).getTime();
  if (!Number.isFinite(t)) return false;
  return (now - t) < SKIP_MS;
}
const staticData = $getWorkflowStaticData('global');
staticData.scannedDistricts = [];
staticData.clippedDistricts = [];
const seen = new Set();
const cells = [];
let skipped = 0;
for (const r of rows) {
  const lat = Number(r.lat);
  const lon = Number(r.lon);
  const yogun = !!(r[YOGUN_KEY] ?? r.yogun_bolge ?? r.yogunBolge);
  const son = r.son_tarama ?? r.sonTarama ?? null;
  if (isFresh(son)) { skipped += 1; continue; }
  const key = `${r.il}|${r.ilce}`;
  if (!seen.has(key)) {
    seen.add(key);
    staticData.scannedDistricts.push({ il: r.il, ilce: r.ilce });
  }
  if (yogun) {
    const offsets = [[-OFFSET,-OFFSET],[-OFFSET,OFFSET],[OFFSET,-OFFSET],[OFFSET,OFFSET]];
    offsets.forEach((o, idx) => {
      cells.push({
        supabaseUrl: cfg.supabaseUrl, supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
        il: r.il, ilce: r.ilce, yogun: true, cellKind: 'nearby_sub', cellIndex: idx,
        latitude: lat + o[0], longitude: lon + o[1], radius: 3000, depth: 0,
      });
    });
  } else {
    cells.push({
      supabaseUrl: cfg.supabaseUrl, supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
      il: r.il, ilce: r.ilce, yogun: false, cellKind: 'nearby', cellIndex: 0,
      latitude: lat, longitude: lon, radius: 5000, depth: 0,
    });
  }
}
staticData.skipAll = cells.length === 0;
staticData.skippedDistrictCount = skipped;
staticData.queuedDistrictCount = seen.size;
staticData.initialCellCount = cells.length;
staticData.yogunDistrictCount = [...seen].filter(k => {
  // counted via cells with yogun flag
  return false;
}).length;
staticData.yogunCellCount = cells.filter(c => c.yogun).length;
staticData.sparseCellCount = cells.filter(c => !c.yogun).length;

if (!cells.length) {
  return [{ json: { skipAll: true, supabaseUrl: cfg.supabaseUrl, supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
    skippedDistrictCount: skipped, queuedDistrictCount: 0, message: 'Tum ilceler skip' } }];
}
return cells.map(c => ({ json: c }));

const cells = $('Split Nearby Batches').all().map(i => i.json);
const responses = $input.all();
const staticData = $getWorkflowStaticData('global');
if (!staticData.placesById) staticData.placesById = {};
if (!staticData.nearbyLogs) staticData.nearbyLogs = [];
if (!staticData.placesApiErrors) staticData.placesApiErrors = [];
if (!staticData.clippedDistricts) staticData.clippedDistricts = [];
const clippedSet = new Set(staticData.clippedDistricts.map(d => d.il + '|' + d.ilce));
function parseIlceIl(formattedAddress) {
  if (!formattedAddress) return { ilce: null, il: null };
  const match = String(formattedAddress).match(/\b\d{5}\s+(.+?),\s*T\u00fcrkiye\s*$/);
  if (!match) return { ilce: null, il: null };
  const parts = match[1].split('/').map(s => s.trim());
  if (parts.length < 2) return { ilce: null, il: null };
  return { il: parts[parts.length - 1], ilce: parts[parts.length - 2] };
}
function kaliteBayragi(isim) {
  if (!isim) return null;
  const kelimeSayisi = isim.trim().split(/\s+/).length;
  if (kelimeSayisi <= 2 && /^[a-zA-Z\s]+$/.test(isim)) return 'suspicious_name';
  return null;
}

function isClosedStatus(status) {
  if (!status) return false;
  const s = String(status).toUpperCase();
  return s === 'CLOSED_PERMANENTLY' || s === 'CLOSED_TEMPORARILY';
}
function isPetOrVetSignal(primaryType, types, isim) {
  const tipSet = new Set(['pet_store', 'veterinary_care', 'pet_care']);
  if (primaryType && tipSet.has(primaryType)) return true;
  if (Array.isArray(types) && types.some((t) => tipSet.has(t))) return true;
  const u = String(isim || '').toLocaleUpperCase('tr-TR');
  if (!u) return false;
  if (
    u.includes('PETSHOP') ||
    u.includes('PET SHOP') ||
    u.includes('PET STORE') ||
    u.includes('PET MARKET') ||
    u.includes('PET FOOD') ||
    u.includes('VETER') ||
    u.includes('AKVARYUM') ||
    u.includes('HAYVAN') ||
    u.includes('PATİ') ||
    u.includes('PATI')
  ) return true;
  if (u.includes(' PET') || u.startsWith('PET ')) return true;
  return false;
}

const out = [];
for (let i = 0; i < responses.length; i++) {
  const cell = cells[i] || cells[0] || {};
  const raw = responses[i].json || {};
  const statusCode = raw.statusCode || null;
  let body = raw.body !== undefined ? raw.body : raw;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (_) { body = {}; }
  }
  const places = (body && Array.isArray(body.places)) ? body.places : [];
  const count = places.length;
  const clipped = count >= 20;
  const depth = Number(cell.depth) || 0;
  const apiError = (statusCode && statusCode >= 400) || (body && (body.error || body.message) && !places.length);
  if (apiError) staticData.placesApiErrors.push({ where: 'nearby', statusCode, il: cell.il, ilce: cell.ilce, error: body.error || body.message || body });
  if (clipped && cell.il && cell.ilce) {
    const ck = cell.il + '|' + cell.ilce;
    if (!clippedSet.has(ck)) { clippedSet.add(ck); staticData.clippedDistricts.push({ il: cell.il, ilce: cell.ilce }); }
  }
  staticData.nearbyLogs.push({
    il: cell.il, ilce: cell.ilce, cellKind: cell.cellKind, cellIndex: cell.cellIndex,
    count, clipped, statusCode, depth,
    lat: cell.latitude, lon: cell.longitude, radius: cell.radius,
    logId: `${cell.il}|${cell.ilce}|${cell.latitude}|${cell.longitude}|${depth}|${cell.cellIndex}`,
  });
  for (const p of places) {
    const id = p.id || (p.name && String(p.name).replace(/^places\//, ''));
    if (!id || staticData.placesById[id]) continue;
    if (isClosedStatus(p.businessStatus)) continue;
    const isim = (p.displayName && p.displayName.text) || null;
    const adres = p.formattedAddress || null;
    const parsed = parseIlceIl(adres);
    staticData.placesById[id] = {
      kaynak: 'google_places', kaynak_id: id, isim, adres,
      ilce: parsed.ilce || cell.ilce || null, il: parsed.il || cell.il || null,
      lat: p.location ? p.location.latitude : null, lon: p.location ? p.location.longitude : null,
      google_types: Array.isArray(p.types) ? p.types : null, primary_type: p.primaryType || null,
      kalite_bayragi: kaliteBayragi(isim), _source: 'nearby',
    };
  }
  out.push({ json: {
    supabaseUrl: cell.supabaseUrl, supabaseServiceRoleKey: cell.supabaseServiceRoleKey,
    cellResultCount: count, clipped, statusCode, depth,
    accumulated: Object.keys(staticData.placesById).length,
  }});
}
return out.length ? out : [{ json: { accumulated: Object.keys(staticData.placesById).length } }];

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const queued = new Set((staticData.scannedDistricts || []).map(d => `${d.il}|${d.ilce}`));
const rows = $('Fetch Ilce Merkezleri').all().map(i => {
  let r = i.json;
  if (Array.isArray(r)) return null;
  return r;
}).filter(Boolean);

// Fetch returns one item that is array sometimes — normalize
let districts = [];
const first = $('Expand Ilce Rows').all().map(i => i.json);
districts = first.filter(r => r && r.il && r.ilce);

const variations = ['evcil hayvan maması', 'kuş yemi', 'pet shop'];
const out = [];
for (const r of districts) {
  const yogun = !!(r['yoğun_bolge'] ?? r.yogun_bolge);
  if (!yogun) continue;
  if (!queued.has(`${r.il}|${r.ilce}`)) continue; // bu koşuda taranmayan yoğun ilçe
  for (const v of variations) {
    out.push({
      json: {
        supabaseUrl: cfg.supabaseUrl,
