      }
    });
  }
}
if (!out.length) {
  return [{
    json: {
      supabaseUrl: cfg.supabaseUrl,
      supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
      skipText: true,
      message: 'Text Search kuyrugu bos',
    }
  }];
}
return out;

