    }
  });
}
return out.length ? out : [{ json: { accumulated: Object.keys(staticData.placesById).length } }];

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const places = Object.values(staticData.placesById || {});
return [{
  json: {
    supabaseUrl: cfg.supabaseUrl,
    supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
    placeCount: places.length,
    nearbyLogCount: (staticData.nearbyLogs || []).length,
    clippedCells: (staticData.nearbyLogs || []).filter(l => l.clipped).length,
  }
}];

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
// Sadece bu koşuda YENİ kaynak_id'ler — mevcut satırlarda eşleştirme yeniden hesaplanmaz
const places = Array.isArray(staticData.yeniPlaces) ? staticData.yeniPlaces : [];

let musteriler = $input.first().json;
if (musteriler.body !== undefined) musteriler = musteriler.body;
if (typeof musteriler === 'string') {
  try { musteriler = JSON.parse(musteriler); } catch (_) { musteriler = []; }
}
if (!Array.isArray(musteriler)) musteriler = [];

// TODO: fuzzy eşik — kalibrasyon gerekiyor
const HIGH = 85;
const LOW = 60;

function normalize(name) {
  if (!name) return '';
  return String(name)
    .toLocaleUpperCase('tr-TR')
    .replace(/\b(LTD\.?\s?ŞTİ\.?|A\.?Ş\.?|TİC\.?|SAN\.?|PAZ\.?|VE\b)/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenSimilarity(a, b) {
  // Token-based Jaccard * 100 — sıra toleranslı (düz Levenshtein değil)
  const ta = new Set(normalize(a).split(' ').filter(Boolean));
  const tb = new Set(normalize(b).split(' ').filter(Boolean));
  if (!ta.size || !tb.size) return 0;
  let inter = 0;
  for (const t of ta) if (tb.has(t)) inter += 1;
  const union = ta.size + tb.size - inter;
  return Math.round((inter / union) * 100);
}

function foldIlce(s) {
  if (!s) return '';
  return String(s).replace(/İ/g, 'i').replace(/I/g, 'ı').toLocaleLowerCase('tr-TR').trim();
}

const cust = musteriler.map(m => ({
  kod: m.musteri_kodu,
  unvan: m.unvan,
  norm: normalize(m.unvan),
  ilce: foldIlce(m.ilce),
}));

const upserts = [];
for (const p of places) {
  const norm = normalize(p.isim);
  let best = { score: 0, kod: null, ilceOk: false };
  for (const c of cust) {
    const score = tokenSimilarity(norm, c.norm);
    if (score > best.score) {
      best = { score, kod: c.kod, ilceOk: foldIlce(p.ilce) === c.ilce && !!c.ilce };
    }
  }
  let eslesme_durumu = 'yeni';
  let eslesen = null;
  if (best.score >= HIGH && best.ilceOk) {
    eslesme_durumu = 'mevcut_musteri';
    eslesen = best.kod;
  } else if (best.score >= HIGH && !best.ilceOk) {
    eslesme_durumu = 'manuel_kontrol';
    eslesen = best.kod;
  } else if (best.score >= LOW) {
    eslesme_durumu = 'manuel_kontrol';
    eslesen = best.kod;
  }
  upserts.push({
    kaynak: 'google_places',
    kaynak_id: p.kaynak_id,
    isim: p.isim,
    isim_normalized: norm,
    adres: p.adres,
    ilce: p.ilce,
    il: p.il,
    lat: p.lat,
    lon: p.lon,
    google_types: p.google_types,
    primary_type: p.primary_type,
    kalite_bayragi: p.kalite_bayragi,
    eslesme_durumu,
    eslesen_musteri_kodu: eslesen,
  });
}

const BATCH = 100;
const batches = [];
for (let i = 0; i < upserts.length; i += BATCH) {
  batches.push({
    json: {
      supabaseUrl: cfg.supabaseUrl,
      supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
      batchIndex: Math.floor(i / BATCH),
      total: upserts.length,
      rows: upserts.slice(i, i + BATCH),
    }
  });
}
if (!batches.length) {
  return [{ json: { supabaseUrl: cfg.supabaseUrl, supabaseServiceRoleKey: cfg.supabaseServiceRoleKey, total: 0, rows: [], empty: true } }];
}
return batches;

const staticData = $getWorkflowStaticData('global');
const clipped = (staticData.nearbyLogs || []).filter(l => l.clipped);
const placeTotal = Object.keys(staticData.placesById || {}).length;
const apiErrors = staticData.placesApiErrors || [];
const nearbyOk = (staticData.nearbyLogs || []).filter(l => l.statusCode === 200).length;
const nearby429 = apiErrors.filter(e => e.statusCode === 429).length;
let markStatus = null;
for (const it of $input.all()) markStatus = it.json.statusCode || markStatus;
const initial = staticData.initialCellCount || 0;
const d1 = staticData.deepenPass1Count || 0;
const d2 = staticData.deepenPass2Count || 0;
return [{ json: {
  skipAll: !!staticData.skipAll,
  skippedDistrictCount: staticData.skippedDistrictCount || 0,
  queuedDistrictCount: staticData.queuedDistrictCount || 0,
  // Grid muhasebesi — HTTP oncesi uretilen hucre sayilari
  initialCellCount: initial,
  sparseCellCount: staticData.sparseCellCount || 0,
  yogunCellCount: staticData.yogunCellCount || 0,
  deepenPass1Cells: d1,
  deepenPass2Cells: d2,
