  nearbyHttp429: nearby429,
  placeTotal,
  newPlaceCount: (staticData.yeniPlaces || []).length,
  existingPlaceCount: (staticData.mevcutPlaces || []).length,
  placesApiErrorCount: apiErrors.length,
  placesApiErrorSample: apiErrors.slice(0, 3),
