  clippedDistricts: staticData.clippedDistricts || [],
  remainingClippedAtMaxDepth: clipped.filter(l => (Number(l.depth)||0) >= 2 && l.clipped).length,
  markedScanned: (staticData.scannedDistricts || []).length,
  markHttpStatus: markStatus,
  pacing: { batchSize: 1, batchIntervalMs: 250, retryOnFail: false },
  message: `cells init=${initial} deep=${d1}+${d2} places=${placeTotal} 429=${nearby429}`,
}}];

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const districts = staticData.scannedDistricts || [];
const clipped = staticData.clippedDistricts || [];
const apiErrors = staticData.placesApiErrors || [];
const placeTotal = Object.keys(staticData.placesById || {}).length;
const now = new Date().toISOString();
if (!staticData.skipAll && placeTotal === 0) {
  throw new Error('Mark engellendi: placeTotal=0');
}
// 429 alan ilceleri son_tarama yazma — tekrar kuyruga kalsin
const failed = new Set();
for (const e of apiErrors) {
  if (e && e.statusCode === 429 && e.il && e.ilce) failed.add(e.il + '|' + e.ilce);
}
const sonRows = [];
for (const d of districts) {
  const k = d.il + '|' + d.ilce;
  if (failed.has(k)) continue;
  sonRows.push({ il: d.il, ilce: d.ilce, son_tarama: now });
}
const yogunRows = clipped.map(d => ({ il: d.il, ilce: d.ilce, 'yo\u011fun_bolge': true }));
return [{ json: {
  supabaseUrl: cfg.supabaseUrl,
  supabaseServiceRoleKey: cfg.supabaseServiceRoleKey,
  sonRows,
  yogunRows,
  rows: sonRows, // Has Mark Rows? uyumu
  placeTotal,
  failedDistrictCount: failed.size,
  clippedDistrictCount: clipped.length,
}}];

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const places = Object.values(staticData.placesById || {});

function asIdRows(inputItems) {
  if (!inputItems.length) return [];
  if (inputItems.length > 1) {
    return inputItems.map((i) => i.json).filter((r) => r && (r.kaynak_id || r.kaynakId));
  }
  let body = inputItems[0].json;
  if (Array.isArray(body)) return body;
  if (body && Array.isArray(body.body)) return body.body;
  if (body && typeof body.body === 'string') {
    try {
      const parsed = JSON.parse(body.body);
      if (Array.isArray(parsed)) return parsed;
    } catch (_) {}
  }
  if (typeof body === 'string') {
    try {
      const parsed = JSON.parse(body);
      if (Array.isArray(parsed)) return parsed;
      body = parsed;
    } catch (_) {}
  }
